/* 
  Decime Tortuga - Design System
  Colors based on provided brand imagery.
*/

:root {
    /* Brand Colors */
    --primary-green: #0b9347; /* Inspired by the storefront and logo background */
    --primary-yellow: #fded00; /* Inspired by the logo text/turtle */
    --dark-green: #07642f;

    /* Neutral Colors */
    --text-dark: #1a1a1a;
    --text-light: #666666;
    --bg-light: #f5f7fa;
    --white: #ffffff;

    /* Effects */
    --shadow-sm: 0 2px 8px rgba(0,0,0,0.05);
    --shadow-md: 0 8px 24px rgba(0,0,0,0.1);
    --border-radius: 12px;
    --transition: all 0.3s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Outfit', sans-serif;
    background-color: var(--bg-light);
    color: var(--text-dark);
    line-height: 1.6;
}

/* Typography */
h1, h2, h3, h4 {
    font-weight: 800;
}

/* Navigation Bar */
.navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 5%;
    background-color: var(--primary-green);
    color: var(--white);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: var(--shadow-md);
}

.logo {
    font-size: 1.8rem;
    color: var(--white);
    letter-spacing: 1px;
}

.logo .highlight {
    color: var(--primary-yellow);
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-item {
    color: var(--white);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
    padding: 0.5rem;
}

.nav-item:hover, .nav-item.active {
    color: var(--primary-yellow);
}

.dropdown {
    position: relative;
    display: inline-block;
}

.dropdown-content {
    display: none;
    position: absolute;
    background-color: var(--white);
    min-width: 160px;
    box-shadow: var(--shadow-md);
    border-radius: var(--border-radius);
    overflow: hidden;
    z-index: 1;
    top: 100%;
}

.dropdown-content a {
    color: var(--text-dark);
    padding: 12px 16px;
    text-decoration: none;
    display: block;
    font-size: 0.9rem;
    transition: var(--transition);
}

.dropdown-content a:hover {
    background-color: var(--bg-light);
    color: var(--primary-green);
}

.dropdown:hover .dropdown-content {
    display: block;
}

.nav-actions {
    display: flex;
    gap: 1rem;
}

.icon-btn {
    background: none;
    border: none;
    color: var(--white);
    font-size: 1.2rem;
    cursor: pointer;
    transition: var(--transition);
    position: relative;
}

.icon-btn:hover {
    color: var(--primary-yellow);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background-color: var(--primary-yellow);
    color: var(--text-dark);
    font-size: 0.7rem;
    font-weight: 800;
    border-radius: 50%;
    padding: 2px 6px;
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, rgba(11,147,71,0.9) 0%, rgba(7,100,47,0.9) 100%), url('https://images.unsplash.com/photo-1450778869180-41d0601e046e?ixlib=rb-4.0.3&auto=format&fit=crop&w=1500&q=80') center/cover;
    height: 60vh;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: var(--white);
    padding: 0 20px;
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.hero-content p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    max-width: 600px;
    margin-inline: auto;
}

.primary-btn {
    background-color: var(--primary-yellow);
    color: var(--text-dark);
    border: none;
    padding: 12px 28px;
    font-size: 1rem;
    font-weight: 800;
    border-radius: 30px;
    cursor: pointer;
    transition: var(--transition);
    box-shadow: var(--shadow-sm);
}

.primary-btn:hover {
    background-color: var(--white);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

/* Main Container */
.container {
    max-width: 1200px;
    margin: 3rem auto;
    padding: 0 20px;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
}

.section-header h3 {
    font-size: 1.8rem;
    color: var(--primary-green);
}

.search-bar {
    display: flex;
    align-items: center;
    background: var(--white);
    padding: 8px 16px;
    border-radius: 20px;
    box-shadow: var(--shadow-sm);
}

.search-bar input {
    border: none;
    outline: none;
    padding-left: 10px;
    font-family: inherit;
}

.search-bar i {
    color: var(--text-light);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--white);
    border-radius: var(--border-radius);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-5px);
    box-shadow: var(--shadow-md);
}

.product-img {
    width: 100%;
    height: 200px;
    object-fit: cover;
}

.product-info {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-category {
    font-size: 0.8rem;
    color: var(--text-light);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 0.5rem;
}

.product-title {
    font-size: 1.1rem;
    margin-bottom: 1rem;
    color: var(--text-dark);
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: auto;
}

.product-price {
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--primary-green);
}

.add-to-cart-btn {
    background-color: var(--primary-green);
    color: var(--white);
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    cursor: pointer;
    transition: var(--transition);
    display: flex;
    align-items: center;
    justify-content: center;
}

.add-to-cart-btn:hover {
    background-color: var(--primary-yellow);
    color: var(--text-dark);
}

/* Cart Sidebar */
.cart-sidebar {
    position: fixed;
    top: 0;
    right: -400px;
    width: 100%;
    max-width: 400px;
    height: 100vh;
    background: var(--white);
    box-shadow: -5px 0 15px rgba(0,0,0,0.1);
    z-index: 1000;
    display: flex;
    flex-direction: column;
    transition: right 0.4s ease;
}

.cart-sidebar.open {
    right: 0;
}

.cart-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid #eee;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.5rem;
    cursor: pointer;
    color: var(--text-light);
    transition: var(--transition);
}

.close-btn:hover {
    color: var(--text-dark);
}

.cart-items {
    flex-grow: 1;
    overflow-y: auto;
    padding: 1.5rem;
}

.cart-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #eee;
}

.cart-item img {
    width: 60px;
    height: 60px;
    border-radius: 8px;
    object-fit: cover;
}

.cart-item-info {
    flex-grow: 1;
}

.cart-item-info h4 {
    font-size: 0.9rem;
    margin-bottom: 0.3rem;
}

.cart-item-price {
    font-weight: 600;
    color: var(--primary-green);
}

.qty-controls {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.qty-btn {
    background: var(--bg-light);
    border: none;
    width: 24px;
    height: 24px;
    border-radius: 4px;
    cursor: pointer;
}

.remove-item {
    color: #ff4d4f;
    background: none;
    border: none;
    cursor: pointer;
}

.cart-footer {
    padding: 1.5rem;
    border-top: 1px solid #eee;
    background: var(--bg-light);
}

.cart-total {
    display: flex;
    justify-content: space-between;
    font-size: 1.25rem;
    font-weight: 800;
    margin-bottom: 1rem;
}

.checkout-btn {
    width: 100%;
    background: var(--primary-green);
    color: var(--white);
    border: none;
    padding: 12px;
    font-size: 1rem;
    font-weight: 600;
    border-radius: var(--border-radius);
    cursor: pointer;
    transition: var(--transition);
}

.checkout-btn:hover {
    background: var(--dark-green);
}

/* Overlay for Sidebar and Modal */
.overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0,0,0,0.5);
    z-index: 999;
    display: none;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.overlay.active {
    display: block;
    opacity: 1;
}

/* Auth Modal (Glassmorphism inspired) */
.auth-modal {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.9);
    width: 90%;
    max-width: 400px;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    border-radius: var(--border-radius);
    box-shadow: 0 15px 35px rgba(0,0,0,0.2);
    z-index: 1001;
    opacity: 0;
    pointer-events: none;
    transition: all 0.3s ease;
}

.auth-modal.open {
    opacity: 1;
    pointer-events: all;
    transform: translate(-50%, -50%) scale(1);
}

.modal-content {
    padding: 2rem;
    position: relative;
}

.auth-modal .close-btn {
    position: absolute;
    top: 15px;
    right: 15px;
}

.auth-tabs {
    display: flex;
    margin-bottom: 1.5rem;
    border-bottom: 2px solid #eee;
}

.tab-btn {
    flex: 1;
    background: none;
    border: none;
    padding: 10px;
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-light);
    cursor: pointer;
    position: relative;
}

.tab-btn.active {
    color: var(--primary-green);
}

.tab-btn.active::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 100%;
    height: 2px;
    background: var(--primary-green);
}

.auth-form {
    display: none;
}

.auth-form.active {
    display: block;
    animation: fadeIn 0.4s ease;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
    color: var(--text-dark);
}

.form-group input {
    width: 100%;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 8px;
    font-family: inherit;
}

.full-width {
    width: 100%;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Footer */
.footer {
    background: var(--dark-green);
    color: var(--white);
    padding: 3rem 5% 1rem;
    margin-top: 4rem;
}

.footer-content {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-brand h3 {
    color: var(--primary-yellow);
    margin-bottom: 1rem;
}

.footer-links {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.footer-links a {
    color: #ccc;
    text-decoration: none;
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--primary-yellow);
}

.footer-social {
    display: flex;
    gap: 1rem;
}

.footer-social a {
    color: var(--white);
    font-size: 1.5rem;
    transition: var(--transition);
}

.footer-social a:hover {
    color: var(--primary-yellow);
}

.footer-bottom {
    text-align: center;
    border-top: 1px solid rgba(255,255,255,0.1);
    padding-top: 1rem;
    font-size: 0.9rem;
    color: #aaa;
}

/* Responsive */
@media (max-width: 768px) {
    .nav-links {
        display: none; /* In a real app, add a hamburger menu here */
    }
    .hero-content h2 {
        font-size: 2rem;
    }
    .section-header {
        flex-direction: column;
        gap: 1rem;
        align-items: flex-start;
    }
    .search-bar {
        width: 100%;
    }
}

// State Management
let currentCategory = 'all';
let currentSubcategory = null;
let searchQuery = '';
let cart = [];

// DOM Elements
const productGrid = document.getElementById('productGrid');
const categoryTitle = document.getElementById('categoryTitle');
const searchInput = document.getElementById('searchInput');

// Cart DOM Elements
const cartBtn = document.getElementById('cartBtn');
const cartSidebar = document.getElementById('cartSidebar');
const closeCartBtn = document.getElementById('closeCartBtn');
const overlay = document.getElementById('overlay');
const cartItemsContainer = document.getElementById('cartItemsContainer');
const cartTotalValue = document.getElementById('cartTotalValue');
const cartCount = document.getElementById('cartCount');

// Auth DOM Elements
const loginBtn = document.getElementById('loginBtn');
const authModal = document.getElementById('authModal');
const closeAuthBtn = document.getElementById('closeAuthBtn');
const tabBtns = document.querySelectorAll('.tab-btn');
const authForms = document.querySelectorAll('.auth-form');

// Initialize Application
document.addEventListener('DOMContentLoaded', () => {
    // Load cart from localStorage if exists
    const savedCart = localStorage.getItem('decimeTortugaCart');
    if (savedCart) {
        cart = JSON.parse(savedCart);
        updateCartUI();
    }

    renderProducts();
    setupEventListeners();
});

// Setup Event Listeners
function setupEventListeners() {
    // Navigation filtering
    document.querySelectorAll('.nav-item').forEach(item => {
        item.addEventListener('click', (e) => {
            if (!item.closest('.dropdown')) {
                // Main category click without dropdown or "all"
                e.preventDefault();
                currentCategory = e.target.getAttribute('data-category');
                currentSubcategory = null;
                updateActiveNav(e.target);
                renderProducts();
            } else if (e.target.hasAttribute('data-category')) {
                // Dropdown parent click
                e.preventDefault();
                currentCategory = e.target.getAttribute('data-category');
                currentSubcategory = null;
                updateActiveNav(e.target);
                renderProducts();
            }
        });
    });

    document.querySelectorAll('.dropdown-content a').forEach(item => {
        item.addEventListener('click', (e) => {
            e.preventDefault();
            const parentNav = e.target.closest('.dropdown').querySelector('.nav-item');
            currentCategory = parentNav.getAttribute('data-category');
            currentSubcategory = e.target.getAttribute('data-subcategory');
            updateActiveNav(parentNav);
            renderProducts();
        });
    });

    // Search filtering
    searchInput.addEventListener('input', (e) => {
        searchQuery = e.target.value.toLowerCase();
        renderProducts();
    });

    // Cart Sidebar Toggles
    cartBtn.addEventListener('click', () => toggleSidebar(cartSidebar));
    closeCartBtn.addEventListener('click', () => toggleSidebar(cartSidebar));
    overlay.addEventListener('click', () => {
        cartSidebar.classList.remove('open');
        authModal.classList.remove('open');
        overlay.classList.remove('active');
    });

    // Auth Modal Toggles
    loginBtn.addEventListener('click', () => {
        authModal.classList.add('open');
        overlay.classList.add('active');
    });
    closeAuthBtn.addEventListener('click', () => {
        authModal.classList.remove('open');
        overlay.classList.remove('active');
    });

    // Auth Tabs
    tabBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            tabBtns.forEach(t => t.classList.remove('active'));
            authForms.forEach(f => f.classList.remove('active'));

            e.target.classList.add('active');
            const targetForm = document.getElementById(e.target.getAttribute('data-target'));
            targetForm.classList.add('active');
        });
    });

    // Auth Form Submits (Mock)
    document.getElementById('loginForm').addEventListener('submit', (e) => {
        e.preventDefault();
        alert('Sesión iniciada exitosamente (Simulación)');
        authModal.classList.remove('open');
        overlay.classList.remove('active');
    });

    document.getElementById('registerForm').addEventListener('submit', (e) => {
        e.preventDefault();
        alert('Cuenta creada exitosamente (Simulación)');
        authModal.classList.remove('open');
        overlay.classList.remove('active');
    });

    // Shop Now Button
    document.getElementById('shopNowBtn').addEventListener('click', () => {
        document.querySelector('.container').scrollIntoView({ behavior: 'smooth' });
    });
}

function updateActiveNav(activeElement) {
    document.querySelectorAll('.nav-item').forEach(nav => nav.classList.remove('active'));
    activeElement.classList.add('active');

    // Update Title
    let title = "Todos los Productos";
    if (currentCategory === 'dogs') title = "Perros";
    if (currentCategory === 'cats') title = "Gatos";
    if (currentCategory === 'other') title = "Otras Mascotas";
    if (currentCategory === 'accessories') title = "Accesorios";

    if (currentSubcategory) {
        title += ` - ${currentSubcategory.charAt(0).toUpperCase() + currentSubcategory.slice(1).replace('-', ' ')}`;
    }

    categoryTitle.textContent = title;
}

// Render Products Logic
function renderProducts() {
    let filteredProducts = products;

    // Filter by Category
    if (currentCategory !== 'all') {
        filteredProducts = filteredProducts.filter(p => p.category === currentCategory);
    }

    // Filter by Subcategory
    if (currentSubcategory) {
        filteredProducts = filteredProducts.filter(p => p.subcategory === currentSubcategory);
    }

    // Filter by Search Query
    if (searchQuery) {
        filteredProducts = filteredProducts.filter(p => 
            p.name.toLowerCase().includes(searchQuery) || 
            p.category.toLowerCase().includes(searchQuery)
        );
    }

    // Render HTML
    productGrid.innerHTML = '';

    if (filteredProducts.length === 0) {
        productGrid.innerHTML = '<p style="grid-column: 1/-1; text-align: center; color: var(--text-light);">No se encontraron productos.</p>';
        return;
    }

    filteredProducts.forEach(product => {
        const card = document.createElement('div');
        card.className = 'product-card';
        card.innerHTML = `
            <img src="${product.image}" alt="${product.name}" class="product-img">
            <div class="product-info">
                <span class="product-category">${product.category}</span>
                <h4 class="product-title">${product.name}</h4>
                <div class="product-footer">
                    <span class="product-price">$${product.price.toFixed(2)}</span>
                    <button class="add-to-cart-btn" onclick="addToCart(${product.id})" aria-label="Agregar al carrito">
                        <i class="fa-solid fa-plus"></i>
                    </button>
                </div>
            </div>
        `;
        productGrid.appendChild(card);
    });
}

// Cart Logic
function addToCart(productId) {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const existingItem = cart.find(item => item.id === productId);

    if (existingItem) {
        existingItem.quantity += 1;
    } else {
        cart.push({ ...product, quantity: 1 });
    }

    updateCartUI();

    // Optional: Visual feedback
    cartBtn.classList.add('bounce');
    setTimeout(() => cartBtn.classList.remove('bounce'), 300);
}

function removeFromCart(productId) {
    cart = cart.filter(item => item.id !== productId);
    updateCartUI();
}

function updateQuantity(productId, delta) {
    const item = cart.find(i => i.id === productId);
    if (item) {
        item.quantity += delta;
        if (item.quantity <= 0) {
            removeFromCart(productId);
        } else {
            updateCartUI();
        }
    }
}

function updateCartUI() {
    // Save to localStorage
    localStorage.setItem('decimeTortugaCart', JSON.stringify(cart));

    // Update Count
    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);
    cartCount.textContent = totalItems;

    // Render Cart Items
    cartItemsContainer.innerHTML = '';
    let totalValue = 0;

    if (cart.length === 0) {
        cartItemsContainer.innerHTML = '<p style="text-align: center; color: var(--text-light); margin-top: 2rem;">Tu carrito está vacío.</p>';
    } else {
        cart.forEach(item => {
            totalValue += item.price * item.quantity;
            const cartItemEl = document.createElement('div');
            cartItemEl.className = 'cart-item';
            cartItemEl.innerHTML = `
                <img src="${item.image}" alt="${item.name}">
                <div class="cart-item-info">
                    <h4>${item.name}</h4>
                    <span class="cart-item-price">$${(item.price * item.quantity).toFixed(2)}</span>
                    <div class="qty-controls">
                        <button class="qty-btn" onclick="updateQuantity(${item.id}, -1)">-</button>
                        <span>${item.quantity}</span>
                        <button class="qty-btn" onclick="updateQuantity(${item.id}, 1)">+</button>
                    </div>
                </div>
                <button class="remove-item" onclick="removeFromCart(${item.id})">
                    <i class="fa-solid fa-trash"></i>
                </button>
            `;
            cartItemsContainer.appendChild(cartItemEl);
        });
    }

    // Update Total Value
    cartTotalValue.textContent = `$${totalValue.toFixed(2)}`;
}

// Utility functions
function toggleSidebar(sidebar) {
    sidebar.classList.toggle('open');
    if (sidebar.classList.contains('open')) {
        overlay.classList.add('active');
    } else {
        overlay.classList.remove('active');
    }
}

// Add CSS animation for bounce
const style = document.createElement('style');
style.innerHTML = `
    @keyframes bounce {
        0%, 100% { transform: scale(1); }
        50% { transform: scale(1.2); }
    }
    .bounce {
        animation: bounce 0.3s ease;
    }
`;
document.head.appendChild(style);
